<style>
.sales-summary-theme { --ss-burgundy:#441827; --ss-teal:#1B4242; --ss-sage:#5C8374; --ss-cream:#F5F2B8; --ss-border:rgba(92,131,116,.28); color:#263B38; }
.sales-summary-theme .summary-card { border:1px solid var(--ss-border); border-radius:1rem; overflow:hidden; }
.sales-summary-theme .summary-header,.sales-summary-theme .modal-header { background:linear-gradient(115deg,var(--ss-burgundy),var(--ss-teal) 72%,var(--ss-sage)); color:#fff; padding:1.25rem; }
.sales-summary-theme .summary-header h4,.sales-summary-theme .modal-title { color:#fff; }
.sales-summary-theme .summary-header p { color:#eee; font-size:.875rem; }
.sales-summary-theme .summary-scope,.sales-summary-theme .summary-stat { border:1px solid var(--ss-border); border-radius:.8rem; padding:1rem; background:#FBF9E8; }
.sales-summary-theme .summary-stat strong { display:block; font-size:1.35rem; margin-top:.3rem; color:var(--ss-teal); overflow-wrap:anywhere; }
.sales-summary-theme .summary-tabs { gap:.25rem; background:rgba(92,131,116,.08); padding:.35rem; border-radius:.8rem; }
.sales-summary-theme .summary-tabs .nav-link { color:var(--ss-teal); font-weight:600; border-radius:.65rem; }
.sales-summary-theme .summary-tabs .nav-link.active { background:var(--ss-teal); color:var(--ss-cream); }
.sales-summary-theme .table thead th { background:var(--ss-teal)!important; color:var(--ss-cream)!important; border-bottom:2px solid var(--ss-sage); white-space:nowrap; }
.sales-summary-theme .table tfoot { background:#FBF9E8; font-weight:600; }
.sales-summary-theme .btn-success { background:var(--ss-teal); border-color:var(--ss-teal); color:#fff; }
.sales-summary-theme .btn-success:hover { background:#143333; }
.sales-summary-theme .form-control:focus,.sales-summary-theme .form-select:focus { border-color:var(--ss-sage); box-shadow:0 0 0 .2rem rgba(92,131,116,.2); }
.sales-summary-theme .modal-content { border:0; border-radius:1rem; overflow:hidden; }
.sales-summary-theme .modal-footer { background:#FBF9E8; }
.sales-summary-theme .table-responsive { overflow-x:auto; }
@media(max-width:575.98px) { .sales-summary-theme .summary-stat { padding:.75rem; } .sales-summary-theme .summary-stat strong { font-size:1.05rem; } .sales-summary-theme .summary-header { padding:1rem; } }
</style>
